diff --git a/src/main/java/hotel/reports/CsvReport.java b/src/main/java/hotel/reports/CsvReport.java
new file mode 100644
index 0000000..ba91edd
--- /dev/null
+++ b/src/main/java/hotel/reports/CsvReport.java
@@ -0,0 +1,36 @@
+package hotel.reports;
+
+import java.util.List;
+
+/**
+ * The shape every CSV report shares: a title line (inn, report name, period), the header, the lines
+ * (rows, then the total). Each report supplies only its name, header and lines.
+ *
+ * @param <P> what the report is asked about: a night, a month
+ */
+abstract class CsvReport<P> {
+
+    private static final String INN = "Pousada Maré Alta";
+
+    private final String name;
+
+    CsvReport(String name) {
+        this.name = name;
+    }
+
+    public final String generate(P period) {
+        StringBuilder csv = new StringBuilder();
+        csv.append(INN).append(',').append(name).append(',').append(period).append('\n');
+        csv.append(header()).append('\n');
+        for (String line : lines(period)) {
+            csv.append(line).append('\n');
+        }
+        return csv.toString();
+    }
+
+    /** The column names, comma separated. */
+    abstract String header();
+
+    /** The rows of the report, followed by its total line. */
+    abstract List<String> lines(P period);
+}
diff --git a/src/main/java/hotel/reports/MonthReservations.java b/src/main/java/hotel/reports/MonthReservations.java
new file mode 100644
index 0000000..5a5830a
--- /dev/null
+++ b/src/main/java/hotel/reports/MonthReservations.java
@@ -0,0 +1,38 @@
+package hotel.reports;
+
+import hotel.reservations.Reservation;
+import hotel.reservations.ReservationStore;
+import java.time.YearMonth;
+import java.util.ArrayList;
+import java.util.Comparator;
+import java.util.List;
+import java.util.function.Predicate;
+
+/** The reservations that start in a month, in the order the monthly reports list them. */
+final class MonthReservations {
+
+    private MonthReservations() {
+    }
+
+    /** Those the inn kept money from; a cancelled non-refundable reservation counts. */
+    static List<Reservation> withRevenue(ReservationStore store, YearMonth month) {
+        return startingIn(store, month, reservation -> reservation.amountKept().signum() > 0);
+    }
+
+    /** Those the guest paid and did not cancel: confirmed, checked in or checked out. */
+    static List<Reservation> paid(ReservationStore store, YearMonth month) {
+        return startingIn(store, month, Reservation::isPaid);
+    }
+
+    private static List<Reservation> startingIn(
+            ReservationStore store, YearMonth month, Predicate<Reservation> condition) {
+        List<Reservation> found = new ArrayList<>();
+        for (Reservation reservation : store.all()) {
+            if (condition.test(reservation) && YearMonth.from(reservation.checkIn()).equals(month)) {
+                found.add(reservation);
+            }
+        }
+        found.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
+        return found;
+    }
+}
